const utc = value => typeof value === "string" && value.endsWith("Z") ? Date.parse(value) : NaN;
const price = value => Number.isFinite(value) && value > 0;
return $input.all().map(({json}, index) => {
  const {signals, candles, roundTripCost} = json;
  if (!Array.isArray(signals) || !Array.isArray(candles) || !Number.isFinite(roundTripCost) || roundTripCost < 0) {
    throw new Error("Expected signals, closed candles and round-trip cost");
  }
  const bars = candles.map(bar => ({...bar, start:utc(bar.openTime), end:utc(bar.closeTime)}))
    .sort((a,b) => a.start-b.start);
  for (const [i, bar] of bars.entries()) {
    if (!Number.isFinite(bar.start) || !Number.isFinite(bar.end) || bar.start >= bar.end ||
        i > 0 && bars[i-1].end > bar.start ||
        ![bar.open,bar.high,bar.low,bar.close].every(price) ||
        bar.low > Math.min(bar.open,bar.close) || bar.high < Math.max(bar.open,bar.close)) {
      throw new Error("Invalid or overlapping replay candle");
    }
  }
  const events = signals.map(signal => {
    const at = utc(signal.confirmedAt);
    if (!Number.isFinite(at) || !["BUY","SELL"].includes(signal.direction) ||
        ![signal.stop,signal.target].every(price)) throw new Error("Invalid replay signal");
    return {...signal, at};
  }).sort((a,b)=>a.at-b.at);
  if (events.some((signal,i)=>i>0 && signal.at===events[i-1].at)) throw new Error("Ambiguous simultaneous replay signals");
  const trades=[], skipped=[];
  let position=null, next=0;
  for (const bar of bars) {
    while (next<events.length && events[next].at<=bar.start) {
      const signal=events[next++];
      const sign=signal.direction==="BUY"?1:-1;
      if (position || (bar.open-signal.stop)*sign<=0 || (signal.target-bar.open)*sign<=0) {
        skipped.push({confirmedAt:signal.confirmedAt,reason:position?"POSITION_ALREADY_OPEN":"OPEN_OUTSIDE_PLAN"});
        continue;
      }
      position={direction:signal.direction, stop:signal.stop, target:signal.target, entry:bar.open,
        openedAt:bar.openTime, confirmedAt:signal.confirmedAt, roundTripCost, sign};
    }
    if (!position) continue;
    const {sign,stop,target,...trade}=position;
    const stopHit=sign===1?bar.low<=stop:bar.high>=stop;
    const targetHit=sign===1?bar.high>=target:bar.low<=target;
    const gapStop=(bar.open-stop)*sign<=0;
    const gapTarget=(bar.open-target)*sign>=0;
    if (!stopHit && !targetHit && !gapStop && !gapTarget) continue;
    const stopped=gapStop || (!gapTarget && stopHit);
    trades.push({...trade,stop,target,exit:stopped?(gapStop?bar.open:stop):target,
      closedAt:gapStop||gapTarget?bar.openTime:bar.closeTime,reason:stopped?"STOP":"TARGET"});
    position=null;
  }
  const pendingSignals=events.slice(next).map(({confirmedAt})=>confirmedAt);
  return {json:{trades,skipped,pendingSignals,openPosition:position!==null},pairedItem:{item:index}};
});
